<tr><td>\u6D6E\u70B9\u6253\u5370\u3001\u5927\u6BB5 sprintf</td><td>\u8017\u65F6\u957F\uFF0C\u53EF\u80FD\u91CD\u5165</td><td>\u53EA\u5B58\u6570\u636E\uFF0C\u4E3B\u5FAA\u73AF\u6253\u5370</td></tr>
